"""Write sw_manifest.js for the web app's offline service worker (web/sw.js).

Run after `flutter build web --no-web-resources-cdn`:

    python scripts/pwa_manifest.py src/support_sphere/build/web
"""
import argparse
import hashlib
import json
import re
import sys
from pathlib import Path

# The worker caches CanvasKit itself (only the variant the browser uses);
# the rest are generated by this step or never loaded by the running app.
# Dotfiles (.last_build_id, .gitkeep) are skipped too: a host that doesn't
# serve them would make the whole precache, and so the install, fail.
SKIP_DIRS = {"canvaskit"}
SKIP_NAMES = {"sw.js", "sw_manifest.js", "flutter_service_worker.js", "NOTICES"}
SKIP_SUFFIXES = {".symbols", ".map"}


def shell_files(build_dir: Path) -> list[Path]:
    files = []
    for path in sorted(build_dir.rglob("*")):
        rel = path.relative_to(build_dir)
        if (
            path.is_file()
            and rel.parts[0] not in SKIP_DIRS
            and rel.name not in SKIP_NAMES
            and rel.suffix not in SKIP_SUFFIXES
            and not any(part.startswith(".") for part in rel.parts)
        ):
            files.append(rel)
    return files


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("build_dir", type=Path, help="flutter build web output")
    args = parser.parse_args()
    build_dir = args.build_dir

    bootstrap = (build_dir / "flutter_bootstrap.js").read_text()
    match = re.search(r'"engineRevision":"([0-9a-f]+)"', bootstrap)
    if not match:
        sys.exit(f"engineRevision not found in {build_dir}/flutter_bootstrap.js")
    if not (build_dir / "canvaskit").is_dir():
        sys.exit("canvaskit/ missing: build with --no-web-resources-cdn")

    files = shell_files(build_dir)
    digest = hashlib.sha256()
    for rel in files:
        digest.update(rel.as_posix().encode())
        digest.update((build_dir / rel).read_bytes())

    # index.html is cached under the scope root, which is what navigations hit.
    urls = ["" if rel.as_posix() == "index.html" else rel.as_posix() for rel in files]
    manifest = {
        "version": digest.hexdigest()[:16],
        "engineRevision": match.group(1),
        "files": urls,
    }
    out = build_dir / "sw_manifest.js"
    out.write_text(
        "// Generated by scripts/pwa_manifest.py; do not edit.\n"
        f"self.PWA_MANIFEST = {json.dumps(manifest, indent=2)};\n"
    )
    print(f"Wrote {out}: {len(urls)} files, version {manifest['version']}")


if __name__ == "__main__":
    main()
